// The form of a todo: the zod schema that checks the inputs, the conversions between the
// API and the form values, and the display helpers of the pages.
// Generated by spinup g resource. The application owns this file.
import { z } from 'zod';
import type { components } from '#lib/api/schema.js';

/** Item is a todo as the API returns it. */
export type Item = components['schemas']['Todo'];
/** Input is the JSON body of a create or a full update. */
export type Input = components['schemas']['TodoInput'];
/** Problem is an API error (RFC 9457 problem details). */
export type Problem = components['schemas']['Problem'];

/** schema checks the form values. Superforms also reads the values of a new todo from it. */
export const schema = z.object({
	title: z.string().trim().min(1, 'Title is required.'),
	done: z.boolean(),
	due: z.string().trim().regex(/^(\d{4}-\d{2}-\d{2})?$/, 'Enter a date.'),
	priority: z.enum(['low', 'normal', 'high'], { error: 'Choose the priority.' })
});

/** Values holds the form values of a todo. */
export type Values = z.infer<typeof schema>;

/** The labels of the priority values. */
export const priorityLabels: Record<NonNullable<Item['priority']>, string> = {
	low: 'Low',
	normal: 'Normal',
	high: 'High'
};

/** fromItem returns the form values of a todo, for the edit form. */
export function fromItem(item: Item): Values {
	return {
		title: item.title,
		done: item.done,
		due: item.due ?? '',
		priority: item.priority
	};
}

/** toBody returns the JSON body of the API for checked form values. */
export function toBody(values: Values): Input {
	return {
		title: values.title,
		done: values.done,
		due: values.due === '' ? null : values.due,
		priority: values.priority
	};
}

/** itemTitle returns the name of a todo in headings and links. */
export function itemTitle(item: Item): string {
	return item.title || `Todo ${item.id}`;
}

// A date has no time zone. Format it in UTC, so the day does not shift.
const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeZone: 'UTC' });

/** formatDate formats a date such as 2026-10-16 for the reader. */
export function formatDate(value: string): string {
	return dateFormat.format(new Date(value));
}

const timeFormat = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' });

/** formatTime formats an instant in the time zone of the reader. */
export function formatTime(value: string): string {
	return timeFormat.format(new Date(value));
}

/** problemMessage returns the text of an API problem. */
export function problemMessage(problem: Problem | undefined, status: number): string {
	return problem?.detail ?? problem?.title ?? `The API returned status ${status}.`;
}
